const { visualRoutes } = require('./panel-visual-bindings')
const { switchMapping } = require('./control-type-model')

function configuredRoutes (config) {
  return visualRoutes(config)
}

function resolveBoundCommand (routes, message) {
  const request = message?._controlPanel
  if (request?.kind !== 'command' || typeof request.id !== 'string') {
    throw new Error('Invalid bound command')
  }
  const route = routes.get(request.id)
  if (!route) throw new Error(`Unknown control ID: ${request.id}`)
  if (route.control.mode === 'read' || ['meter', 'xy-series'].includes(route.control.type)) {
    throw new Error(`Read-only control: ${request.id}`)
  }
  if (!route.binding?.device || !route.binding.writePath) {
    throw new Error(`Incomplete command binding: ${request.id}`)
  }
  if (!Object.hasOwn(request, 'value')) throw new Error('Bound command needs a value')
  const value = request.value
  const type = route.control.type
  if (['level', 'dimmer', 'position'].includes(type) &&
    (typeof value !== 'number' || !Number.isFinite(value))) {
    throw new Error(`${type} value must be a finite number`)
  }
  const metadata = route.binding.writeMeta
  if (['level', 'dimmer', 'position'].includes(type) && metadata?.type === 'integer' && !Number.isInteger(value)) {
    throw new Error(`${type} value must be an integer`)
  }
  if (['level', 'dimmer', 'position'].includes(type) &&
    ((Number.isFinite(metadata?.min) && value < metadata.min) ||
      (Number.isFinite(metadata?.max) && value > metadata.max))) {
    throw new Error(`${type} value is outside the device range`)
  }
  if (['mute', 'power'].includes(type) && typeof value !== 'boolean') {
    throw new Error(`${type} value must be a boolean`)
  }
  if (['source', 'preset'].includes(type) &&
    !(typeof value === 'string' || (typeof value === 'number' && Number.isFinite(value)))) {
    throw new Error(`${type} value must be a string or number`)
  }
  if (type === 'text' && (typeof value !== 'string' || value.length > 4096)) {
    throw new Error('Text value must be a string under 4096 characters')
  }
  const mapping = ['mute', 'power'].includes(type) && metadata?.booleanMapping
    ? switchMapping(metadata, metadata.booleanMapping) : null
  const payload = mapping ? (value ? mapping.trueValue : mapping.falseValue)
    : ['mute', 'power'].includes(type) && metadata?.booleanEncoding === 'integer01'
      ? (value ? 1 : 0) : value
  if (Array.isArray(metadata?.enums) && metadata.enums.length &&
    !metadata.enums.some(entry => Object.is(entry, payload) || Object.is(entry?.value, payload))) {
    throw new Error('Value is not a permitted device option')
  }
  return {
    kind: 'bound-command',
    controlId: request.id,
    controlType: type,
    device: route.binding.device,
    path: route.binding.writePath,
    payload,
    final: request.final === true
  }
}

function resolveBoundFeedback (routes, message) {
  if (message?.kind !== 'device-feedback' || typeof message.device !== 'string' ||
    typeof message.path !== 'string' || !Object.hasOwn(message, 'payload')) {
    throw new Error('Invalid device feedback')
  }
  const matches = []
  for (const [id, route] of routes) {
    if (route.control.mode === 'write' || route.binding?.device !== message.device ||
      route.binding.readPath !== message.path || route.binding.readMeta?.meter ||
      route.binding.readMeta?.xySeries) continue
    const type = route.control.type
    const metadata = route.binding.readMeta
    let value = message.payload
    if (['mute', 'power'].includes(type)) {
      if (metadata?.booleanMapping) {
        const mapping = switchMapping(metadata, metadata.booleanMapping)
        // Integer/float Event nodes can deliver numeric values as strings.
        if (['integer', 'float'].includes(metadata.type) && typeof value === 'string' && value.trim()) value = Number(value)
        if (metadata.type === 'boolean') {
          if (value === 'true' || value === 1 || value === '1') value = true
          else if (value === 'false' || value === 0 || value === '0') value = false
        }
        if (Object.is(value, mapping.trueValue)) value = true
        else if (Object.is(value, mapping.falseValue)) value = false
        else throw new Error(`Invalid ${type} feedback: ${id}`)
      } else if (value === 'true' || value === 1 || value === '1') value = true
      else if (value === 'false' || value === 0 || value === '0') value = false
      if (typeof value !== 'boolean') throw new Error(`Invalid ${type} feedback: ${id}`)
    } else if (['level', 'dimmer', 'position', 'meter'].includes(type)) {
      if (typeof value === 'string' && value.trim() !== '') value = Number(value)
      if (typeof value !== 'number' || !Number.isFinite(value) ||
        (metadata?.type === 'integer' && !Number.isInteger(value)) ||
        (Number.isFinite(metadata?.min) && value < metadata.min) ||
        (Number.isFinite(metadata?.max) && value > metadata.max)) {
        throw new Error(`Invalid ${type} feedback: ${id}`)
      }
    } else if (['source', 'preset'].includes(type) &&
      !(typeof value === 'string' || (typeof value === 'number' && Number.isFinite(value)))) {
      throw new Error(`Invalid ${type} feedback: ${id}`)
    } else if (type === 'text' && (typeof value !== 'string' || value.length > 4096)) {
      throw new Error(`Invalid text feedback: ${id}`)
    }
    matches.push({ id, value })
  }
  if (!matches.length) throw new Error('Unmapped device feedback')
  return matches
}

module.exports = { configuredRoutes, resolveBoundCommand, resolveBoundFeedback }
